package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

public class Element_append_TriageGen2Test {

    @Test
    public void testAppendNullHtml() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        try {
            element.append(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected exception
        }
    }

    @Test
    public void testAppendNonNullHtml() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        Tag tag = Parser.parseBodyFragment("<p></p>", "baseUri").body().childNodes().get(0).tag();
        element.appendChild(new Node(tag));
        element.append("<p></p>");
        assertEquals(2, element.childNodes().size());
    }

    @Test
    public void testAppendHtmlWithMultipleNodes() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        Tag tag1 = Parser.parseBodyFragment("<p>node1</p>", "baseUri").body().childNodes().get(0).tag();
        Tag tag2 = Parser.parseBodyFragment("<p>node2</p>", "baseUri").body().childNodes().get(0).tag();
        Tag tag3 = Parser.parseBodyFragment("<p>node3</p>", "baseUri").body().childNodes().get(0).tag();
        element.appendChild(new Node(tag1));
        element.appendChild(new Node(tag2));
        element.append("<p>node4</p>");
        assertEquals(4, element.childNodes().size());
    }

    @Test
    public void testAppendHtmlWithEmptyString() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        element.append("");
        assertEquals(1, element.childNodes().size());
    }

    @Test
    public void testAppendHtmlWithWhitespaceString() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        element.append("   ");
        assertEquals(1, element.childNodes().size());
    }

    @Test
    public void testAppendHtmlWithHtmlComment() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        element.append("<!-- comment -->");
        assertEquals(1, element.childNodes().size());
    }

    @Test
    public void testAppendHtmlWithHtmlDoctype() {
        Element element = new Element(Tag.tag("test"), "baseUri");
        element.append("<!DOCTYPE HTML>");
        assertEquals(1, element.childNodes().size());
    }
}
